from pathlib import Path
ROOT=Path("/root/autodl-tmp/symbolic_dynamics")
P=ROOT/"docs/papers211_215_sequence/qa/p211_round2_physical_independent01"
checks=0
def need(x,s):
 global checks
 checks+=1
 if not x: raise AssertionError(s)
def pin(b): return {"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest()}
def meta(s): return {k:getattr(s,"st_"+v) for k,v in (("mode","mode"),("device","dev"),("inode","ino"),("uid","uid"),("gid","gid"),("nlink","nlink"),("size","size"),("mtime_ns","mtime_ns"),("ctime_ns","ctime_ns"))}
def rich(q):
 q=Path(q); a,b=q.lstat(),q.stat(); raw=q.read_bytes()
 z={**pin(raw),"resolved":str(q.resolve(strict=True)),"symlink":os.readlink(q) if q.is_symlink() else None,"stat":meta(b),"lstat":meta(a)}
 need(meta(q.lstat())==z["lstat"] and meta(q.stat())==z["stat"],"stable read")
 return z
def obj(q): return json.loads(q.read_bytes())
base={"PLAN.md","receive_physical.py","capture_once.py","DERIVATION.diff","DERIVATION_NATIVE.json","NATIVE_READS.json","CORRECTIONS_NATIVE.json","close_documentary.py","INPUTS.sha256","FINDINGS.json","REPORT.md"}
attempt_names={"CHECKS_ATTEMPT.json","CHECKS_NATIVE.json","CHECKS.stdout.raw","CHECKS.stderr.raw","EXECUTED_RECEIVER_SOURCE.py","EXECUTED_CAPTURE_SOURCE.py","RESULT.json"}
expected=base|attempt_names
for n in range(2,6):
 suffix=str(n).zfill(2)
 expected|={"receive_physical"+suffix+".py","capture"+suffix+".py"}
 expected|={"run"+suffix+"/"+x for x in attempt_names}
expected.add("closing01/RESULT.json")
for lab in ("01_source_cmp","02_source_cmp","03_source_cmp","04_external_pins"):
 expected|={"closing01/"+lab+"/"+x for x in ("ATTEMPT.json","NATIVE.json","stdout.raw","stderr.raw")}
 if lab!="04_external_pins": expected.add("closing01/"+lab+"/stdin.raw")
need(len(expected)==74,"expected preseal74")
expected_dirs={"run02","run03","run04","run05","closing01",*("closing01/"+x for x in ("01_source_cmp","02_source_cmp","03_source_cmp","04_external_pins"))}
files=set(); dirs=set()
for q in P.rglob("*"):
 rel=str(q.relative_to(P)); s=q.lstat()
 need(not stat.S_ISLNK(s.st_mode),"no symlink")
 if stat.S_ISREG(s.st_mode):
  need(s.st_nlink==1,"all owned payloads ordinary exclusive inode")
  files.add(rel)
 else:
  need(stat.S_ISDIR(s.st_mode),"no special")
  dirs.add(rel)
need(files==expected and dirs==expected_dirs,["exact entire owned membership",sorted(files-expected),sorted(expected-files)])
pins={r:pin((P/r).read_bytes()) for r in sorted(files)}
need(pins["receive_physical05.py"]=={"bytes":77479,"sha256":"ad8bd8890f9d5415d2a0499485415cb42858eca9c48b04cdecaf7b9c4c0c0e9d"},"unchanged successful helper")
need(pins["run05/CHECKS.stdout.raw"]=={"bytes":3430632,"sha256":"ff715a36ffd80ada101e64bf39085606155d7ea3c87beefe80555910fee84fdc"},"whole actual main unchanged")
need(pins["closing01/RESULT.json"]=={"bytes":12390,"sha256":"d42f79a3df6dd87634deffeef75080b04589e2d6ac36401e244a6296ec3c0122"},"whole closing unchanged")
union={}
for n in range(1,6):
 d=P if n==1 else P/("run"+str(n).zfill(2))
 source=P/("receive_physical.py" if n==1 else "receive_physical"+str(n).zfill(2)+".py")
 capture=P/("capture_once.py" if n==1 else "capture"+str(n).zfill(2)+".py")
 need(source.read_bytes()==(d/"EXECUTED_RECEIVER_SOURCE.py").read_bytes(),"entire actual preserved source")
 need(capture.read_bytes()==(d/"EXECUTED_CAPTURE_SOURCE.py").read_bytes(),"entire actual preserved capture")
 a=obj(d/"CHECKS_ATTEMPT.json"); z=obj(d/"CHECKS_NATIVE.json")
 need(a["source_pin"]==pin(source.read_bytes()) and a["capture_source_pin"]==pin(capture.read_bytes()),"all original source pins")
 need(z["native_exit_code"]==(0 if n==5 else 1) and z["exception"] is None,"complete real attempts unchanged")
 for label in ("stdout","stderr"):
  raw=(d/("CHECKS."+label+".raw")).read_bytes()
  need(z[label]=={"path":"CHECKS."+label+".raw",**pin(raw)},"every entire attempt raw pin")
  if label=="stderr": need(raw==b"","actual empty error stream")
 x=obj(d/"CHECKS.stdout.raw")
 key=x["READ_INPUTS"] if n==5 else x["READ_INPUTS_PARTIAL"]
 for path,value in key.items():
  need(path not in union or union[path]==value,"whole original union key consistent")
  union[path]=value
need(len(union)==4829,"whole all-attempt input key")
for path,value in union.items(): need(rich(path)==value,["original rich endpoint unchanged",path])
manifest=(P/"INPUTS.sha256").read_text()
external={}
for line in manifest.splitlines():
 m=re.fullmatch(r"([0-9a-f]{64})  (/.+)",line)
 need(m is not None,"whole external manifest grammar")
 h,path=m.groups()
 need(path not in external and not Path(path).is_relative_to(P),"unique outside own package")
 external[path]=h
 need(hashlib.sha256(Path(path).read_bytes()).hexdigest()==h,["whole external input bytes",path])
need(len(external)==4820,"all4820 external")
close=obj(P/"closing01/RESULT.json")
need(close["checks"]==60198 and close["all_attempt_original_rich_paths"]==4829 and len(close["complete_source_bindings"])==9,"actual closing full result")
need(len(close["native_commands"])==4,"closing native4")
for i,c in enumerate(close["native_commands"],1):
 d=P/"closing01"/c["label"]; a=obj(d/"ATTEMPT.json"); z=obj(d/"NATIVE.json")
 need(c=={"label":c["label"],**z} and all(z[k]==v for k,v in a.items()),"whole saved closing receipt")
 need(z["native_exit_code"]==0 and z["exception"] is None and z["stream_capture_status"]=="captured","actual closing native pass")
 need(pin((d/"stdout.raw").read_bytes())==z["stdout"] and pin((d/"stderr.raw").read_bytes())==z["stderr"] and (d/"stderr.raw").read_bytes()==b"","whole closing raw")
 if i<=3:
  need((d/"stdout.raw").read_bytes()==b"" and pin((d/"stdin.raw").read_bytes())==z["input_pin"],"whole saved cmp stdin")
  need((d/"stdin.raw").read_bytes()==Path(z["origin"]["path"]).read_bytes(),"entire original source native input")
 else:
  need((d/"stdout.raw").read_bytes()=="".join(p+": OK\n" for p in sorted(external)).encode(),"full native4820SHA output")
need(len(obj(P/"NATIVE_READS.json")["records"])==36,"preserved actual36read records")
links=[]
for href in re.findall(r"\[[^\]]*\]\(([^)]+)\)",(P/"REPORT.md").read_text()):
 if re.match(r"^[a-z]+:",href): continue
 target=href.split("#",1)[0]
 if target in ("CLOSING_NATIVE.json","SHA256SUMS"):
  need(not (P/target).exists(),"only two exact pending final appendices")
  links.append({"href":href,"status":"pending_exact_final_appendix"})
 else:
  q=(P/target).resolve(strict=True); need(q.is_file(),"whole final report local target exists")
  links.append({"href":href,"status":"exists","pin":pin(q.read_bytes())})
need(all(pin((P/r).read_bytes())==v for r,v in pins.items()),"all74 whole preseal bytes stable")
print(json.dumps({"status":"PASS_COMPLETE_PRESEAL_MEMBERSHIP_INPUT_KEYS_AND_FINAL_REPORT_PIN","checks":checks,"payloads":len(pins),"payload_bytes":sum(v["bytes"] for v in pins.values()),"directories":sorted(dirs),"all_original_rich_paths":len(union),"external_original_rows":len(external),"report_local_links":links,"first_report_preseal_pin":pins["REPORT.md"],"payload_pins":pins,"allowed_next_appends":["CLOSING_NATIVE.json","SHA256SUMS"],"science":False,"build":False,"submitted_code_execution":False},sort_keys=True,indent=2))
'

